import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';

const supabaseUrl = String.fromEnvironment('SUPABASE_URL', defaultValue: 'https://bpyhfufefpjraefcovrw.supabase.co');
const supabaseKey = String.fromEnvironment('SUPABASE_ANON_KEY', defaultValue: 'sb_publishable_F1KtKcCl_MdJtrAMPLjiuA_uYxqKxmo');
const logo64 = '';
const photo64 = '';

Future<void> main() async { WidgetsFlutterBinding.ensureInitialized(); await Supabase.initialize(url: supabaseUrl, publishableKey: supabaseKey); runApp(const RuralzApp()); }
final db = Supabase.instance.client;
class RuralzApp extends StatelessWidget { const RuralzApp({super.key}); @override Widget build(BuildContext context) => MaterialApp(debugShowCheckedModeBanner:false, title:'Ruralz - Maths', theme:ThemeData(useMaterial3:true,colorSchemeSeed:const Color(0xFF2E7D5B),scaffoldBackgroundColor:const Color(0xFFF3FBF6)),home:const Splash()); }
class Splash extends StatefulWidget { const Splash({super.key}); @override State<Splash> createState()=>_SplashState(); }
class _SplashState extends State<Splash> { @override void initState(){super.initState();Future.delayed(const Duration(seconds:10),(){if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>const Home()));});} @override Widget build(BuildContext context)=>Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Image.memory(base64Decode(logo64),width:240,height:190,fit:BoxFit.contain),const SizedBox(height:16),ClipOval(child:Image.memory(base64Decode(photo64),width:120,height:120,fit:BoxFit.cover)),const SizedBox(height:14),const Text('Ruralz - Maths',style:TextStyle(fontSize:28,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('Enriching Hopes',style:TextStyle(letterSpacing:3)),const SizedBox(height:18),const Text('Developed by D. K. Chavan sir'),const SizedBox(height:8),const Text('MHT-CET Mathematics • Offline Test Series')]))));} }
class Home extends StatelessWidget { const Home({super.key}); @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Ruralz - Maths')),body:FutureBuilder<List<dynamic>>(future:db.from('topics').select('id,name,sort_order').order('sort_order'),builder:(context,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Text('Unable to load topics: ${s.error}'));final rows=s.data??<dynamic>[];return ListView(padding:const EdgeInsets.all(16),children:[Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:const Color(0xFFE4F5E9),borderRadius:BorderRadius.circular(20)),child:const Text('MHT-CET Mathematics\nOffline Test Series',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold))),const SizedBox(height:16),...rows.map((t)=>Card(child:ListTile(title:Text(t['name'].toString()),subtitle:const Text('20 tests • 50 questions per test'),trailing:const Icon(Icons.chevron_right),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>Tests(topicId:t['id'].toString(),name:t['name'].toString())))))]);})); }
class Tests extends StatelessWidget { final String topicId,name; const Tests({super.key,required this.topicId,required this.name}); @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(name)),body:FutureBuilder<List<dynamic>>(future:db.from('tests').select('id,title,question_count,duration_minutes').eq('topic_id',topicId).order('test_number'),builder:(context,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Text('${s.error}'));final rows=s.data??<dynamic>[];return ListView.builder(itemCount:rows.length,itemBuilder:(context,i)=>ListTile(title:Text(rows[i]['title'].toString()),subtitle:Text('${rows[i]['question_count']} questions • ${rows[i]['duration_minutes']} minutes')));}));} }
